          [t-group]="gridProperties?.group"
          [t-groupable]="gridProperties?.groupable"
          [t-hide-select-all]="gridProperties?.hideSelectAll"
          [t-selectable]="true"
          [t-pageable]="true"
          [t-items]="items"
          [t-columns]="columns"
          [t-loading]="isLoading || isLoadingDisclaimer"
          [t-show-more-disabled]="disabled || !hasNext || gridProperties?.showMoreDisabled"
          [t-header-template]="multiple && selecteds?.length ? templateDisclaimers : undefined"
          [t-height]="tableHeight"
